183	function mergeIntervals(intervals: Array<[number, number]>): Array<[number, number]> {
184	  const sorted = [...intervals].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
185	  const merged: Array<[number, number]> = [];
186	  for (const [s, e] of sorted) {
