218	function intersectSegments(
219	  a: Array<[number, number]>,
220	  b: Array<[number, number]>,
221	): Array<[number, number]> {
222	  const out: Array<[number, number]> = [];
223	  let i = 0;
224	  let j = 0;
225	  while (i < a.length && j < b.length) {
226	    const lo = Math.max(a[i][0], b[j][0]);
227	    const hi = Math.min(a[i][1], b[j][1]);
228	    if (lo < hi) out.push([lo, hi]);
229	    if (a[i][1] < b[j][1]) i++;
230	    else j++;
231	  }
232	  return out;
233	}
