577	  const suffix = caseId.replace(/[^A-Za-z0-9._-]/g, '-');
578	  const revFile = join(dir, `rev-${suffix}.json`);
579	  copyFileSync(pristineFile, revFile);
580	  const revItems = items.map((i) => ({...i, groups: i.groups.map((g) => [...g].reverse())}));
581	  const revManifest = writeManifest(dir, `rev-${suffix}.plan.json`, revItems);
582	  const r = runCli(revFile, ['schedule-flex', revManifest]);
583	  const storeBefore = readStore(pristineFile);
584	  const ctx = describeCase(caseId, storeBefore, revItems, expected, detail ? `${detail}；组内候选倒序` : '组内候选倒序');
585	
586	  if (expected === null) {
587	    assert.equal(r.status, 1, `${ctx}\n倒序书写无解结论应一致`);
588	    assert.match(r.stderr, /无整体解/, `${ctx}\n倒序书写无解原因应一致`);
589	    assert.ok(readFileSync(pristineFile).equals(readFileSync(revFile)), `${ctx}\n倒序无解数据逐字节不变`);
590	    return;
591	  }
592	  assert.equal(r.status, 0, `${ctx}\n倒序书写应同样有解，实际 ${r.status}\nstderr:\n${r.stderr}`);
593	  const storeAfter = readStore(revFile);
594	  const firstSeq = storeBefore.bookingSeq + 1;
595	  expected.forEach((p, i) => {
596	    const b = storeAfter.bookings.find((x) => x.id === `B${String(firstSeq + i).padStart(4, '0')}`)!;
597	    assert.equal(b.start, fmtMin(p.startMin), `${ctx}\n倒序书写开始必须一致`);
598	    assert.equal(b.end, fmtMin(p.endMin), `${ctx}\n倒序书写结束必须一致`);
599	    assert.deepEqual(b.resourceIds, [...p.picks].sort(), `${ctx}\n倒序书写资源取舍必须一致`);
600	  });
601	}
