function assertAnchor(
  caseId: string,
  plan: OraclePlacement[] | null,
  anchor: Array<{start: string; end: string; picks: string[]}> | null,
): void {
  if (plan === null) {
    assert.equal(anchor, null, `[${caseId}] 锚点：对照器判无解`);
    return;
  }
  assert.ok(anchor, `[${caseId}] 对照器判有解，锚点不应为 null`);
