261	
262	  // 清单顺序深度优先：选择已按 (开始分钟, 资源标识序列) 排序，首个完整方案
263	  // 即约定的唯一最小方案；每层对所有后续项做前向检查，剪枝“后续必败”分支
264	  // （该检查只剪“固定前缀下某项已无任何合法选择”的分支，不会误杀解）。
265	  const chosen: PlacementT[] = [];
266	  const completable = (itemIdx: number, p: PlacementT): boolean => {
267	    // 把 p 临时并入后，第 itemIdx 项是否仍存在合法选择
268	    const trial = [...chosen, p];
269	    for (const o of optionsPerItem[itemIdx]) {
