356	function createBooking(dataFile: string, resourceIds: string[], start: string, end: string): void {
357	  const args = ['create-booking', '--start', start, '--end', end];
358	  for (const id of resourceIds) args.push('--resource', id);
359	  mustOk(dataFile, args, `既有预约 ${start}/${end}`);
