  // 唯一可行方案。
  const items: OracleItem[] = [
    {startRaw: '2026-10-12T08:00', endRaw: '2026-10-12T12:00', duration: 60, groups: [['R0001', 'R0002']]},
    {startRaw: '2026-10-12T08:00', endRaw: '2026-10-12T09:00', duration: 60, groups: [['R0001']]},
