443	// ---------------------------------------------------------------------------
444	// 核心核对：对照器结论 vs 经命令行提交后的真实结果（业务字段逐项核对）
445	// ---------------------------------------------------------------------------
446	
447	interface VerifyResult {
448	  oraclePlan: OraclePlacement[] | null;
449	}
450	
451	function verifyFlex(
452	  caseId: string,
453	  dataFile: string,
454	  manifestFile: string,
455	  items: OracleItem[],
456	  detail = '',
457	): VerifyResult {
458	  const bytesBefore = readFileSync(dataFile);
459	  const storeBefore = readStore(dataFile);
460	  const expected = exhaustiveOracle(storeBefore, items);
461	  const ctx = describeCase(caseId, storeBefore, items, expected, detail);
462	  const r = runCli(dataFile, ['schedule-flex', manifestFile]);
463	
464	  if (expected === null) {
465	    assert.equal(r.status, 1, `${ctx}\n\n无整体解案例应退出 1，实际 ${r.status}\nstdout:\n${r.stdout}`);
466	    assert.match(r.stderr, /无整体解/, `${ctx}\n\n应说明无整体解原因\nstderr:\n${r.stderr}`);
467	    assert.ok(
468	      !r.stdout.includes('联合排程成功'),
469	      `${ctx}\n\n无整体解不得报告成功\nstdout:\n${r.stdout}`,
470	    );
471	    assert.ok(
472	      bytesBefore.equals(readFileSync(dataFile)),
473	      `${ctx}\n\n无整体解后数据文件必须逐字节不变`,
474	    );
475	    const storeAfter = readStore(dataFile);
476	    assert.equal(storeAfter.bookings.length, storeBefore.bookings.length, `${ctx}\n\n不得留下部分预约`);
477	    assert.equal(storeAfter.bookingSeq, storeBefore.bookingSeq, `${ctx}\n\n预约计数不得推进`);
478	    assert.deepEqual(storeAfter.bookings, storeBefore.bookings, `${ctx}\n\n既有预约记录不得变化`);
479	    return {oraclePlan: null};
480	  }
481	
482	  assert.equal(r.status, 0, `${ctx}\n\n有解案例应退出 0，实际 ${r.status}\nstderr:\n${r.stderr}`);
483	
484	  const firstSeq0 = storeBefore.bookingSeq + 1;
485	  const n = items.length;
486	  // 从提交输出解析按清单顺序的逐项安排（开始/结束）与“按需求组顺序”的资源标识；
487	  // 组序信息只存在于本次提交输出（落盘仅存排序后的资源集合），这里只解析业务字段。
488	  const blocks = r.stdout
489	    .split('\n')
490	    .filter((ln) => /^- 第 \d+ 项 ->|^\s+第 \d+ 组:/.test(ln));
491	  const parsedPicks: string[][] = [];
492	  let cur: string[] | null = null;
493	  for (const ln of blocks) {
494	    const hm = /^- 第 (\d+) 项 -> (B\d{4}): (\S+) → (\S+?)（\d+ 分钟）$/.exec(ln);
495	    if (hm) {
496	      assert.equal(
497	        hm[2],
498	        `B${String(firstSeq0 + Number(hm[1]) - 1).padStart(4, '0')}`,
499	        `${ctx}\n\n输出第 ${hm[1]} 项预约标识应按清单顺序连续分配`,
500	      );
501	      assert.equal(hm[3], fmtMin(expected[Number(hm[1]) - 1].startMin), `${ctx}\n\n输出第 ${hm[1]} 项开始`);
502	      assert.equal(hm[4], fmtMin(expected[Number(hm[1]) - 1].endMin), `${ctx}\n\n输出第 ${hm[1]} 项结束`);
503	      cur = [];
504	      parsedPicks.push(cur);
505	      continue;
506	    }
507	    const gm = /^\s+第 (\d+) 组: (R\d{4})（/.exec(ln);
508	    if (gm && cur !== null) cur[Number(gm[1]) - 1] = gm[2];
509	  }
510	  assert.equal(parsedPicks.length, n, `${ctx}\n\n输出应列出全部 ${n} 项`);
511	  expected.forEach((p, i) => {
512	    assert.deepEqual(parsedPicks[i], p.picks, `${ctx}\n\n第 ${i + 1} 项按需求组顺序的资源取舍`);
513	  });
514	
515	  const storeAfter = readStore(dataFile);
516	  const firstSeq = storeBefore.bookingSeq + 1;
517	  const expectedIds = expected.map((_, i) => `B${String(firstSeq + i).padStart(4, '0')}`);
518	
519	  // 数量与计数
520	  assert.equal(storeAfter.bookings.length, storeBefore.bookings.length + n, `${ctx}\n\n新增预约数量`);
521	  assert.equal(storeAfter.bookingSeq, storeBefore.bookingSeq + n, `${ctx}\n\n预约计数推进数量`);
522	
523	  // 既有记录全部不变（逐对象深比较），其他集合不变
524	  const afterById = new Map(storeAfter.bookings.map((b) => [b.id, b]));
525	  for (const old of storeBefore.bookings) {
526	    assert.deepEqual(afterById.get(old.id), old, `${ctx}\n\n既有预约 ${old.id} 不得变化`);
527	  }
528	  assert.deepEqual(storeAfter.resources, storeBefore.resources, `${ctx}\n资源记录不得变化`);
529	  assert.deepEqual(storeAfter.closures, storeBefore.closures, `${ctx}\n停用记录不得变化`);
530	  assert.deepEqual(storeAfter.waitlist, storeBefore.waitlist, `${ctx}\n候补记录不得变化`);
531	  assert.deepEqual(storeAfter.series, storeBefore.series, `${ctx}\n系列记录不得变化`);
532	
533	  // 按清单顺序逐项核对实际开始、结束、按组所选资源（不依赖输出措辞）
534	  expected.forEach((p, i) => {
535	    const id = expectedIds[i];
536	    const b = afterById.get(id);
537	    assert.ok(b, `${ctx}\n\n应存在新预约 ${id}`);
538	    assert.equal(b!.start, fmtMin(p.startMin), `${ctx}\n\n${id} 实际开始必须与对照最小方案一致`);
539	    assert.equal(b!.end, fmtMin(p.endMin), `${ctx}\n\n${id} 实际结束必须与对照最小方案一致`);
540	    // 落盘资源集合按标识排序；按组所选资源经排序后与集合一致，组序另由下述 picks 核对
541	    assert.deepEqual(
542	      b!.resourceIds,
543	      [...p.picks].sort(),
544	      `${ctx}\n\n${id} 实际资源必须与对照最小方案按组所选一致`,
545	    );
546	    assert.equal(b!.status, 'active', `${ctx}\n\n${id} 必须为有效预约`);
547	    assert.equal(b!.seriesId, undefined, `${ctx}\n\n${id} 必须是普通预约（不加入系列）`);
548	  });
549	
550	  // 新进程查询全部新增预约：数量、资源行、有效状态与普通预约身份
551	  const days = [];
552	  for (const b of storeAfter.bookings) {
553	    for (let t = toMin(b.start); t < toMin(b.end); t += 1440) days.push(dateOf(t));
554	  }
555	  const uniqueDays = [...new Set(days)].sort();
556	  const {found: listed, counts} = queryBookingsByDays(dataFile, uniqueDays);
557	  // 逐日数量：当日与 [00:00,次日00:00) 相交的全部记录（含已取消），与列表口径一致
558	  for (const day of uniqueDays) {
559	    const ds = toMin(`${day}T00:00`);
560	    const expectedCount = storeAfter.bookings.filter((b) => toMin(b.start) < ds + 1440 && ds < toMin(b.end)).length;
561	    assert.equal(counts.get(day) ?? 0, expectedCount, `${ctx}\n新进程查询 ${day} 的预约数量`);
562	  }
563	  const nameById = new Map(storeAfter.resources.map((x) => [x.id, x.name]));
564	  for (const id of expectedIds) {
565	    const l = listed.get(id);
566	    assert.ok(l, `${ctx}\n\n新进程查询应可见新预约 ${id}`);
567	    assert.equal(l!.status, '已预约', `${ctx}\n\n${id} 查询状态应为有效`);
568	    assert.equal(l!.hasSeries, false, `${ctx}\n\n${id} 查询结果应无系列归属（普通预约）`);
569	  }
570	  expected.forEach((p, i) => {
571	    const l = listed.get(expectedIds[i])!;
572	    assert.equal(l.start, fmtMin(p.startMin), `${ctx}\n${expectedIds[i]} 查询开始`);
573	    assert.equal(l.end, fmtMin(p.endMin), `${ctx}\n${expectedIds[i]} 查询结束`);
574	    for (const rid of p.picks) {
575	      assert.ok(
576	        l.resourceText.includes(`${rid}（${nameById.get(rid)}）`),
577	        `${ctx}\n${expectedIds[i]} 查询资源行应含 ${rid}（${nameById.get(rid)}），实际: ${l.resourceText}`,
578	      );
579	    }
580	  });
581	
582	  return {oraclePlan: expected};
583	}
584	
585	// 倒序书写组内候选后，在独立数据副本上必须得到同一方案
586	function verifyReversedCandidates(
587	  caseId: string,
588	  pristineFile: string,
589	  dir: string,
590	  items: OracleItem[],
591	  expected: OraclePlacement[] | null,
592	  detail = '',
593	): void {
594	  const suffix = caseId.replace(/[^A-Za-z0-9._-]/g, '-');
595	  const revFile = join(dir, `rev-${suffix}.json`);
596	  copyFileSync(pristineFile, revFile);
597	  const revItems = items.map((i) => ({...i, groups: i.groups.map((g) => [...g].reverse())}));
598	  const revManifest = writeManifest(dir, `rev-${suffix}.plan.json`, revItems);
599	  const r = runCli(revFile, ['schedule-flex', revManifest]);
600	  const storeBefore = readStore(pristineFile);
601	  const ctx = describeCase(caseId, storeBefore, revItems, expected, detail ? `${detail}；组内候选倒序` : '组内候选倒序');
602	
603	  if (expected === null) {
604	    assert.equal(r.status, 1, `${ctx}\n倒序书写无解结论应一致`);
605	    assert.match(r.stderr, /无整体解/, `${ctx}\n倒序书写无解原因应一致`);
606	    assert.ok(readFileSync(pristineFile).equals(readFileSync(revFile)), `${ctx}\n倒序无解数据逐字节不变`);
607	    return;
608	  }
609	  assert.equal(r.status, 0, `${ctx}\n倒序书写应同样有解，实际 ${r.status}\nstderr:\n${r.stderr}`);
610	  // 按需求组顺序解析输出中的资源取舍（与正向提交同格式），逐位与对照方案一致
611	  const revPicks: string[][] = [];
612	  for (const ln of r.stdout.split('\n')) {
613	    const hm = /^- 第 (\d+) 项 -> B\d{4}: \S+ → \S+?（\d+ 分钟）$/.exec(ln);
614	    if (hm) {
615	      revPicks.push([]);
616	      continue;
617	    }
618	    const gm = /^\s+第 (\d+) 组: (R\d{4})（/.exec(ln);
619	    if (gm && revPicks.length > 0) revPicks[revPicks.length - 1][Number(gm[1]) - 1] = gm[2];
620	  }
621	  assert.equal(revPicks.length, expected.length, `${ctx}\n倒序输出项数`);
622	  const storeAfter = readStore(revFile);
623	  const firstSeq = storeBefore.bookingSeq + 1;
624	  expected.forEach((p, i) => {
625	    assert.deepEqual(revPicks[i], p.picks, `${ctx}\n倒序书写按组资源取舍必须一致`);
626	    const b = storeAfter.bookings.find((x) => x.id === `B${String(firstSeq + i).padStart(4, '0')}`)!;
